def objmetrics(g):
    h,w=len(g),len(g[0]); seen=set(); arr=[]
    for y in range(h):
      for x in range(w):
       if not g[y][x] or (y,x) in seen: continue
       stack=[(y,x)]; seen.add((y,x)); cells=[]
       while stack:
        a,b=stack.pop(); cells.append((a,b))
        for da in (-1,0,1):
         for db in (-1,0,1):
          p=(a+da,b+db)
          if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]:
           seen.add(p);stack.append(p)
       arr.append(cells)
    for k,c in enumerate(arr):
      r0=min(y for y,x in c);r1=max(y for y,x in c);c0=min(x for y,x in c);c1=max(x for y,x in c)
      # 4-neighbor components restricted
      rem=set(c); n4=0
      while rem:
       n4+=1; st=[rem.pop()]
       while st:
        y,x=st.pop()
        for p in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
         if p in rem:rem.remove(p);st.append(p)
      arr[k]={'bbox':(r0,r1,c0,c1),'n':len(c),'n4':n4,'rows':[sum(g[y][x]!=0 for x in range(c0,c1+1)) for y in range(r0,r1+1)],'cols':[sum(g[y][x]!=0 for y in range(r0,r1+1)) for x in range(c0,c1+1)]}
    return arr
